namespace ghidra.app.plugin.debug;






using docking;
using docking;
using docking.action;
using docking.action;
using ghidra.app.events;
using ghidra.framework.plugintool;
using ghidra.program.util;
using resources;

public class EventDisplayComponentProvider : ComponentProviderAdapter {
	private JTextArea textArea;
	private JScrollPane scrollPane;
	private JViewport viewport;
	private Point bottom = new Point(0, 10000);
	private DockingAction clearAction;

	public EventDisplayComponentProvider(PluginTool tool, string owner) : base(tool, "Plugin Event Display", owner)
    {
		textArea = new JTextArea(10, 80);
		textArea.setEditable(true);
		scrollPane = new JScrollPane(textArea);
		viewport = scrollPane.getViewport();

		setDefaultWindowPosition(WindowPosition.BOTTOM);
		setTitle("Plugin Event Display");
		setVisible(true);
		createAction();
	}

	/* @Override */
	public JComponent getComponent() {
		return scrollPane;
	}

	public void processEvent(PluginEvent @event) {
		string date = new Date().toString();

		textArea.append(date + "     " + @event.toString());
		printLocationDetails(@event);
		textArea.append("\n");
		viewport.setViewPosition(bottom);
	}

	private void printLocationDetails(PluginEvent @event) {
		if (@event is ProgramLocationPluginEvent) {
			ProgramLocationPluginEvent l = (ProgramLocationPluginEvent) @event;
			ProgramLocation location = l.getLocation();
			textArea.append("\t" + location.toString());
			textArea.append("\n");
		}
	}

	private void createAction() {
		clearAction = new DockingAction("Clear Display", getOwner()) {
			/* @Override */
			public void actionPerformed(ActionContext context) {
				clear();
			}
		};

		clearAction.markHelpUnnecessary();
		clearAction.setEnabled(true);
		Icon icon = Icons.CLEAR_ICON;
		clearAction.setToolBarData(new ToolBarData(icon));
		addLocalAction(clearAction);
	}

	private void clear() {
		textArea.setText("");
	}
}
